#include <iostream>
#include <cstdint>

enum Months : uint8_t {
    JAN = 1, FEB, MAR, APR, MAY, JUN,
    JUL, AUG, SEP, OCT, NOV, DEC
};

enum class Status : uint8_t {
    CONTINUE = 0,
    WON = 1,
    LOST = 2
};

const char* getStatusName(Status s) {
    switch (s) {
        case Status::CONTINUE: return "CONTINUE";
        case Status::WON:      return "WON";
        case Status::LOST:     return "LOST";
    }
    return "UNKNOWN";
}

int main() {
    Months m = FEB;
    std::cout << "Month numeric value: " << static_cast<int>(m) << "\n";

    Status gameStatus = Status::WON;
    std::cout << "Game status: " << getStatusName(gameStatus) << "\n";
    std::cout << "Status underlying integer: " << static_cast<int>(gameStatus) << "\n";

    return 0;
}

#include <iostream>

enum class Status { CONTINUE, WON, LOST };

struct FixedDiceRoller {
    const unsigned int* rolls;
    size_t index;
    size_t count;

    unsigned int rollNext() {
        if (index < count) {
            return rolls[index++];
        }
        return 7;
    }
};

int main() {
    // Deterministic sequence of sums: first roll 4, then subsequent rolls 10, 6, 4
    const unsigned int rollSequence[] = {4, 10, 6, 4};
    FixedDiceRoller roller{rollSequence, 0, 4};

    Status gameStatus = Status::CONTINUE;
    unsigned int myPoint = 0;

    unsigned int firstRoll = roller.rollNext();
    std::cout << "First roll sum: " << firstRoll << "\n";

    switch (firstRoll) {
        case 7:
        case 11:
            gameStatus = Status::WON;
            break;
        case 2:
        case 3:
        case 12:
            gameStatus = Status::LOST;
            break;
        default:
            gameStatus = Status::CONTINUE;
            myPoint = firstRoll;
            std::cout << "Point is " << myPoint << "\n";
            break;
    }

    while (gameStatus == Status::CONTINUE) {
        unsigned int sum = roller.rollNext();
        std::cout << "Player rolled sum: " << sum << "\n";

        if (sum == myPoint) {
            gameStatus = Status::WON;
        } else if (sum == 7) {
            gameStatus = Status::LOST;
        }
    }

    if (gameStatus == Status::WON) {
        std::cout << "Player wins\n";
    } else {
        std::cout << "Player loses\n";
    }

    return 0;
}
